info.description:
a cute logo for your youtube/* Hide the default YouTube logo */
ytd-topbar-logo-renderer svg {
  display: none !important;
}

/* Apply the Sonic GIF */
ytd-topbar-logo-renderer {
  width: 56px !important;
  height: 56px !important;

  background-image: url("https://media.tenor.com/m9lTuhfEtxAAAAAi/sonic-the-hedgehog-sonic.gif");
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;

  image-rendering: pixelated;
}

/* Optional hover bounce */
ytd-topbar-logo-renderer:hover {
  animation: sonicBounce 0.4s infinite alternate;
}

@keyframes sonicBounce {
  from { transform: translateY(0); }
  to   { transform: translateY(-4px); }
}

